SELECT CAST('a' AS NCHAR(5))
-- case
SELECT CAST('a' AS NCHAR)
-- case
SELECT CAST(TIMESTAMP'2024-01-01 12:00:00' AT TIME ZONE 'UTC' AS DATETIME)
-- case
SELECT CAST(TIMESTAMP'2024-01-01 12:00:00' AT TIME ZONE '+00:00' AS DATETIME(3))
-- case
SELECT * FROM JSON_TABLE('[{"a":1}]', '$[*]' COLUMNS (a INT PATH '$.a')) AS jt
-- case
SELECT * FROM JSON_TABLE('[]', '$[*]' COLUMNS (ord FOR ORDINALITY, x VARCHAR(10) PATH '$.x' DEFAULT '"d"' ON EMPTY NULL ON ERROR, y INT EXISTS PATH '$.y', NESTED PATH '$.z[*]' COLUMNS (z INT PATH '$'))) AS jt
-- case
SELECT t.id, jt.x FROM t, JSON_TABLE(t.j, '$[*]' COLUMNS (x VARCHAR(10) PATH '$.x' ERROR ON EMPTY)) AS jt
-- case
SELECT JSON_VALUE('{"a":42}', '$.a' RETURNING UNSIGNED)
-- case
SELECT JSON_VALUE('{"p":12.5}', '$.d' RETURNING DECIMAL(5,2) DEFAULT 0 ON EMPTY DEFAULT 99 ON ERROR)
-- case
SELECT JSON_VALUE('{}', '$.x' RETURNING CHAR(8) NULL ON EMPTY ERROR ON ERROR)
-- case
SELECT 'a' SOUNDS LIKE 'b'
